export const BIRDS = [{"code":"SNGO","name":"Snow Goose","sci":"Anser caerulescens","caption":"","season":"Fall–Winter","id":"A medium-sized white goose with black wing tips and a pink bill marked by a dark \"grin patch.\" Blue morphs are mostly dark with a white head.","habitat":"Open lakes, ponds, rivers, and agricultural fields.","behavior":"Travels in large, noisy flocks, often mixed with Canada and Cackling Geese. Spends most of its time foraging or resting in open fields.","diet":["Vegetation","Seeds","Fruits"],"group":"waterfowl"},{"code":"CACK","name":"Cackling Goose","sci":"Branta hutchinsii","caption":"","season":"Fall–Winter","id":"Looks like a smaller Canada Goose with a stubbier neck. Black head and neck with a white chinstrap, brown back, and pale belly. The small, wide bill meets a square forehead abruptly.","habitat":"Open wetlands, reservoirs, rivers, and farm fields. Roosts on large reservoirs and forages in city parks, along rivers, and on the outskirts of town.","behavior":"Often mixes with other geese in noisy flocks. Look for long, V-shaped \"skeins\" passing overhead.","diet":["Vegetation","Seeds","Fruits"],"group":"waterfowl"},{"code":"CAGO","name":"Canada Goose","sci":"Branta canadensis","caption":"","season":"Year-round","id":"A large, long-necked waterbird. Black head and neck with a white chinstrap, pale breast, and brown back. Bigger and longer-necked than the similar Cackling Goose.","habitat":"Wetlands, reservoirs, rivers, and farm fields. Common on broad lawns in parks, golf courses, and along urban creeks.","behavior":"Forms loud, honking flocks and flies in classic V-formations. Grazes on lawns and grasses and rests near water. Can be aggressive around its nest in spring.","diet":["Vegetation","Seeds","Fruits"],"group":"waterfowl"},{"code":"WODU","name":"Wood Duck","sci":"Aix sponsa","caption":"Female (left), male (right)","season":"Year-round","id":"A slender duck with a crested head and boxy tail. Males are colorful, with iridescent green heads, red eyes, white face stripes, and a reddish-brown breast. Females are gray-brown with white speckling and a white teardrop around the eye.","habitat":"Wooded ponds and streams. Common in city parks with small lakes, and readily uses nest boxes set near water.","behavior":"Tips forward to feed on plants and insects just under the surface. Often perches on branches over water — unusual among ducks.","diet":["Aquatic Invertebrates","Vegetation","Seeds"],"group":"waterfowl"},{"code":"BWTE","name":"Blue-winged Teal","sci":"Spatula discors","caption":"Male (left), female (right)","season":"Spring–Fall","id":"A small, round-headed dabbling duck. Breeding males have a bluish-gray head with a white crescent near the bill, a finely spotted brown body, and a white flank patch.","habitat":"Shallow water with vegetated edges, including city park ponds, golf courses, and stormwater basins.","behavior":"Tips forward to feed on plants and insects just under the surface. Usually seen in small groups, often with other dabbling ducks.","diet":["Aquatic Invertebrates","Seeds","Vegetation"],"group":"waterfowl"},{"code":"CITE","name":"Cinnamon Teal","sci":"Spatula cyanoptera","caption":"Female (left), male (right)","season":"Spring–Summer","id":"A small dabbling duck with a long bill and pale blue wing patches. Breeding males are a rich cinnamon-red with red eyes.","habitat":"Shallow water with vegetated edges, including city park ponds, golf courses, and stormwater basins.","behavior":"Tips forward to feed on plants and insects just under the surface. Usually seen in small groups, often with other dabbling ducks.","diet":["Aquatic Invertebrates","Seeds","Vegetation"],"group":"waterfowl"},{"code":"NOSH","name":"Northern Shoveler","sci":"Spatula clypeata","caption":"Female (left), male (right)","season":"Year-round","id":"A dabbling duck with a long, shovel-shaped bill, pale blue wing patches, and orange feet. Breeding males have a glossy green head, white chest, and rusty sides; females are mottled brown with orange bills.","habitat":"Shallow water with vegetated edges, including city park ponds, golf courses, and stormwater basins.","behavior":"Swims with its bill in the water, sweeping side to side to filter out invertebrates and seeds. Usually seen in small groups, often with other dabbling ducks.","diet":["Aquatic Invertebrates","Seeds","Vegetation"],"group":"waterfowl"},{"code":"GADW","name":"Gadwall","sci":"Mareca strepera","caption":"Females (left), males (right)","season":"Year-round","id":"A slender dabbling duck. Males are finely patterned in gray and brown with a black rump and black bill. Females are warm brown with an orange bill.","habitat":"Shallow water with vegetated edges, including city park ponds, golf courses, and stormwater basins.","behavior":"Tips forward to feed on plants and insects just under the surface. Usually seen in small groups, often with other dabbling ducks.","diet":["Aquatic Invertebrates","Seeds","Vegetation"],"group":"waterfowl"},{"code":"AMWI","name":"American Wigeon","sci":"Mareca americana","caption":"Male (left), female (right)","season":"Fall–Spring","id":"A dabbling duck with a gray-speckled head, brown body, and small pale bill tipped in black. Males show a white crown and bright green eye patch.","habitat":"Shallow water with vegetated edges, plus parks, golf courses, and other open areas.","behavior":"Tips forward to feed on aquatic plants and insects, and also grazes on lawns. Usually seen in small groups, often with other dabbling ducks.","diet":["Vegetation","Aquatic Invertebrates","Terrestrial or Flying Invertebrates","Seeds"],"group":"waterfowl"},{"code":"MALL","name":"Mallard","sci":"Anas platyrhynchos","caption":"Male (left), female (right)","season":"Year-round","id":"The most familiar duck. Males have a glossy green head, yellow bill, white collar, and dark brown breast; females are mottled brown with an orange-and-black bill.","habitat":"Wetlands, lakes, city park ponds, creeks, roadside ditches, and even backyard pools. Readily takes food from people.","behavior":"The classic quack belongs to the female; males give quieter rasping calls. Tips forward to feed on plants and insects just under the surface.","diet":["Aquatic Invertebrates","Seeds","Vegetation"],"group":"waterfowl"},{"code":"NOPI","name":"Northern Pintail","sci":"Anas acuta","caption":"Male (front), female (back)","season":"Fall–Spring","id":"A slender, elegant dabbling duck with a long neck and long, pointed tail. Males have a chocolate-brown head with a white neck stripe and a gray body; females are mottled brown with a plain tan face.","habitat":"Shallow water with vegetated edges, including park ponds, golf courses, stormwater basins, and slow rivers.","behavior":"Tips forward to feed on plants and insects just under the surface. Usually seen in small groups, often with other dabbling ducks.","diet":["Aquatic Invertebrates","Seeds","Vegetation"],"group":"waterfowl"},{"code":"GWTE","name":"Green-winged Teal","sci":"Anas crecca","caption":"Male (left), female (right)","season":"Fall–Spring","id":"A very small dabbling duck with a green wing patch. Males have a brown head with a bold green eye stripe, a gray body, and a vertical white bar on the side; females are mottled cream and brown.","habitat":"Shallow water with vegetated edges, including park ponds, golf courses, stormwater basins, and slow rivers.","behavior":"Tips forward to feed on plants and insects just under the surface. Usually seen in small groups, often with other dabbling ducks.","diet":["Aquatic Invertebrates","Seeds","Vegetation"],"group":"waterfowl"},{"code":"REDH","name":"Redhead","sci":"Aythya americana","caption":"Male (left), female (right)","season":"Year-round, most common in winter","id":"A medium diving duck with a steep, rounded forehead and a gray bill tipped in black. Males have a rusty red head, black breast and tail, and gray body.","habitat":"Breeds on shallow wetlands and ponds. During migration, look for them on city park ponds and reservoirs.","behavior":"Usually dives for food but will also tip forward to dabble. Often mixes in flocks with scaup and wigeon.","diet":["Aquatic Invertebrates","Vegetation","Seeds"],"group":"waterfowl"},{"code":"RNDU","name":"Ring-necked Duck","sci":"Aythya collaris","caption":"Male (left), female (right)","season":"Fall–Spring","id":"A medium diving duck with a peaked, triangular head and a gray bill marked by a white band and black tip. Males are mostly black with pale gray flanks and yellow eyes; females are brown with a paler face.","habitat":"Prefers smaller water than other divers. Look for them on city park ponds, river pools, and treatment ponds deep enough to dive in.","behavior":"Usually found in pairs or small groups, sometimes with scaup or dabbling ducks.","diet":["Aquatic Invertebrates","Vegetation","Seeds"],"group":"waterfowl"},{"code":"LESC","name":"Lesser Scaup","sci":"Aythya affinis","caption":"Female (left), male (right)","season":"Fall–Spring","id":"A medium diving duck with a peaked, dark head. Males have a black head, chest, and rump with a gray back and white flanks; females are dark brown with a white patch at the base of the bill.","habitat":"City park ponds, reservoirs, and river pools deep enough to dive in.","behavior":"Forms large winter flocks, often with other diving ducks. Among the last ducks to arrive in fall and the last to head north again in spring.","diet":["Aquatic Invertebrates","Vegetation"],"group":"waterfowl"},{"code":"BUFF","name":"Bufflehead","sci":"Bucephala albeola","caption":"Male (left), female (right)","season":"Fall–Spring","id":"The smallest diving duck in North America, with a big, round head and short stubby bill. Males have a white body with a dark back and a dark, iridescent head with a large white patch wrapping over the crown; females are dark with a small white cheek spot.","habitat":"City park ponds, reservoirs, and river pools deep enough to dive in. Rarely seen on land.","behavior":"Dives for aquatic invertebrates and swallows prey underwater, popping back to the surface like a cork. Usually in pairs or small groups.","diet":["Aquatic Invertebrates"],"group":"waterfowl"},{"code":"COGE","name":"Common Goldeneye","sci":"Bucephala clangula","caption":"Male (top), female (bottom)","season":"Fall–Winter","id":"A medium diving duck with bright yellow eyes. Males have a glossy green head with a round white cheek patch, black back, and white body; females have a brown head and gray body.","habitat":"City park lakes, reservoirs, river pools, and treatment ponds deep enough to dive in.","behavior":"Found in pairs or small groups and often pushy with other ducks at feeding areas. Courting males throw their heads back against their shoulders, then snap them forward in a showy display.","diet":["Aquatic Invertebrates","Aquatic Vertebrates"],"group":"waterfowl"},{"code":"HOME","name":"Hooded Merganser","sci":"Lophodytes cucullatus","caption":"Female (left), male (right)","season":"Fall–Winter","id":"A small diving duck with a thin bill and a fan-shaped crest it can raise or lower. Males have a black head with a large white patch, white breast, and brown flanks; females are gray-brown with a shaggy cinnamon crest.","habitat":"City park ponds, reservoirs, and river pools deep enough to dive in.","behavior":"Usually in pairs or small groups, sometimes with other small divers. Uses sharp underwater vision to chase fish and aquatic insects.","diet":["Aquatic Invertebrates","Aquatic Vertebrates"],"group":"waterfowl"},{"code":"COME","name":"Common Merganser","sci":"Mergus merganser","caption":"Male (left), female (right)","season":"Year-round, most common in winter","id":"A large, slender diving duck with a thin pinkish-red bill tipped in black. Males have a smooth dark-green head, white body, and black back; females have a rich brown crested head and gray body.","habitat":"Freshwater lakes, ponds, and rivers, including city parks, reservoirs, and river pools.","behavior":"Often swims with its head underwater scouting for fish, then dives in pursuit. Forms large winter flocks with other divers; broods of ducklings sometimes merge after nesting.","diet":["Aquatic Invertebrates","Aquatic Vertebrates"],"group":"waterfowl"},{"code":"WITU","name":"Wild Turkey","sci":"Meleagris gallopavo","caption":"","season":"Year-round","id":"A very large bird with a small, bare head and a dark body finely barred and washed with green and copper iridescence.","habitat":"Wooded and brushy areas with grassy openings. Often found in suburbs with woodlots and nut-bearing trees.","behavior":"Forages on the ground for nuts, berries, and insects, and roosts in trees at night. Males fan their tails and puff up their feathers to display for females in spring.","diet":["Fruits","Seeds","Vegetation","Terrestrial or Flying Invertebrates"],"group":"doves"},{"code":"MODO","name":"Mourning Dove","sci":"Zenaida macroura","caption":"","season":"Year-round, most common in summer","id":"A plump dove with a small head and long, pointed tail. Soft brown overall, with darker wings marked by black spots.","habitat":"Open woodlands, city parks, suburbs, and roadsides. A frequent feeder visitor, especially at ground, platform, and large hopper feeders.","behavior":"Forages on the ground and rests on telephone wires. Wings make a whistling sound at takeoff. Listen for the soft, mournful \"coo-OO-oo-oo-oo\" that gives the bird its name.","diet":["Seeds"],"group":"doves"},{"code":"ROPI","name":"Rock Pigeon","sci":"Columba livia","caption":"","season":"Year-round","id":"A plump, short-legged bird with a small head. Coloration varies, but most are blue-gray with two black wing bars and iridescent teal-and-purple necks.","habitat":"Thrives in cities, where building ledges stand in for its native rocky cliffs. Common in parks, squares, and plazas; prefers seed scattered on the ground.","behavior":"Gathers in flocks and walks the ground pecking at seeds and dropped food.","diet":["Seeds","Fruits","Terrestrial or Flying Invertebrates"],"group":"doves"},{"code":"EUCD","name":"Eurasian Collared-Dove","sci":"Streptopelia decaocto","caption":"","season":"Year-round","id":"A large, pale dove with a small head and square tail. Sandy brown overall with a black crescent on the back of the neck and dark wingtips.","habitat":"Urban and suburban neighborhoods. A frequent feeder visitor, especially for millet at ground, platform, and hopper feeders.","behavior":"Forages on the ground in small to large flocks and roosts on utility wires and treetops. Listen for the repeated three-note \"koo-KOOO-kook\" and a harsh \"hwaah\" when alarmed.","diet":["Seeds","Terrestrial or Flying Invertebrates","Fruits"],"group":"doves"},{"code":"BCHU","name":"Black-chinned Hummingbird","sci":"Archilochus alexandri","caption":"Male (left), female (right): © Colin Woolley","season":"Spring–Summer","id":"A small hummingbird with a straight bill. Greenish above and pale below; males have a black face and chin with a thin, iridescent purple throat band.","habitat":"Areas with tall trees and flowering shrubs, including yards and parks. A regular visitor to sugar-water feeders.","behavior":"Often returns to a favorite high perch between flights. Darts between flowers and hovers to sip nectar, and snatches insects from the air.","diet":["Nectar","Terrestrial or Flying Invertebrates"],"group":"hummingbirds"},{"code":"BTAH","name":"Broad-tailed Hummingbird","sci":"Selasphorus platycercus","caption":"© Robert Martinez","season":"Spring–Summer","id":"A medium hummingbird with a long, straight bill. Bright green above and white below; males have a brilliant magenta throat patch, females cinnamon-washed sides.","habitat":"Meadows, open woodlands, and suburban yards with flower gardens. A regular sugar-water feeder visitor.","behavior":"Darts between flowers and hovers to sip nectar. Males produce a loud, distinctive wing trill while defending feeding spots. Also picks insects from the air and from spiderwebs.","diet":["Nectar","Terrestrial or Flying Invertebrates"],"group":"hummingbirds"},{"code":"AMCO","name":"American Coot","sci":"Fulica americana","caption":"© Colin Woolley","season":"Year-round","id":"A plump black-and-gray waterbird with red eyes and a white bill marked by a dark ring. Yellow-green feet are lobed, not webbed.","habitat":"Almost any water with shoreline plants, including park ponds, marshes, treatment ponds, and roadside ditches.","behavior":"Social, often gathering in large groups alongside ducks. Walks chicken-like on land and both dabbles and dives for food in the water.","diet":["Aquatic Invertebrates","Vegetation"],"group":"waterbirds"},{"code":"KILL","name":"Killdeer","sci":"Charadrius vociferus","caption":"","season":"Year-round","id":"A slender, robin-sized shorebird with long, pointed wings. Brown above and white below, with two bold black chest bands; an orange-brown rump flashes in flight.","habitat":"Open ground with short or no vegetation — lawns, athletic fields, golf courses, and parking lots.","behavior":"Runs in short bursts, stopping to look around. When a predator approaches its ground nest, the adult fakes a broken wing to lead the threat away. Often noisy in flight, calling \"kill-deer.\"","diet":["Terrestrial or Flying Invertebrates"],"group":"waterbirds"},{"code":"RBGU","name":"Ring-billed Gull","sci":"Larus delawarensis","caption":"","season":"Year-round","id":"A medium gull with long wings that extend past the tail when perched. Adults are white with gray wings tipped in black, yellow eyes, and a yellow bill with a black ring; juveniles are mottled brown and gray.","habitat":"Lakes, reservoirs, landfills, parking lots, and anywhere people gather.","behavior":"An opportunistic feeder that will hunt, scavenge, and steal from other birds. A strong, graceful flier on long wings.","diet":["Aquatic Vertebrates","Seeds","Terrestrial or Flying Invertebrates","Mammals","Fruits","Aquatic Invertebrates"],"group":"waterbirds"},{"code":"DCCO","name":"Double-crested Cormorant","sci":"Nannopterum auritum","caption":"","season":"Spring–Fall","id":"A large black waterbird with a long, S-shaped neck and an orange face and bill.","habitat":"Lakes and ponds with fish, including city parks and reservoirs. Nests in colonies of large stick nests on the ground, rocks, or in trees.","behavior":"Swims low in the water with only its head and neck above the surface. After fishing, perches with wings spread wide to dry in the sun.","diet":["Aquatic Vertebrates"],"group":"waterbirds"},{"code":"AWPE","name":"American White Pelican","sci":"Pelecanus erythrorhynchos","caption":"© Bill Schmoker","season":"Spring–Fall","id":"A massive white bird with a long neck and huge yellow-orange bill. Black flight feathers show along the trailing edge of the wings.","habitat":"Lakes, reservoirs, wetlands, and the occasional golf course pond.","behavior":"Travels and forages in large flocks. Dips its bill below the surface to scoop up small fish, then drains the water before swallowing. Often soars high overhead.","diet":["Aquatic Vertebrates","Amphibians and Reptiles"],"group":"waterbirds"},{"code":"GBHE","name":"Great Blue Heron","sci":"Ardea herodias","caption":"© Colin Woolley","season":"Year-round","id":"The largest North American heron, with a six-foot wingspan. Blue-gray overall with a bold black stripe over the eye.","habitat":"Shallow edges of ponds, lakes, and rivers, plus city parks, golf courses, reservoirs, and large lawns where frogs and rodents are easy to catch.","behavior":"Usually solitary, but nests in colonies of large stick nests high in trees. Wades slowly through shallow water and strikes with a lightning stab of the bill. Flies with slow wingbeats and neck tucked back in an S.","diet":["Aquatic Vertebrates","Amphibians and Reptiles","Mammals"],"group":"waterbirds"},{"code":"TUVU","name":"Turkey Vulture","sci":"Cathartes aura","caption":"","season":"Spring–Fall","id":"A large, dark bird with a bare red head. In flight, the wings are held in a shallow V and show silver-gray trailing edges with long, splayed \"fingers\" at the tips.","habitat":"Open country, including roadsides, suburbs, farm fields, and landfills.","behavior":"Teeters from side to side as it rides thermals on outstretched wings, rarely flapping. Forages in small groups and roosts in larger ones.","diet":["Carrion"],"group":"raptors"},{"code":"OSPR","name":"Osprey","sci":"Pandion haliaetus","caption":"© Dawn Wilson","season":"Spring–Fall","id":"A large, slender raptor, brown above and white below, with a white head crossed by a dark eye stripe. In flight, the wings are held in an M shape with dark patches at the wrists.","habitat":"Near rivers, lakes, reservoirs, and ponds, especially where tall posts or platforms offer nest sites. Large stick nests sit out in the open.","behavior":"Patrols over shallow water on steady wingbeats, hovers briefly, then plunges feet-first to snatch fish from the surface.","diet":["Aquatic Vertebrates"],"group":"raptors"},{"code":"SSHA","name":"Sharp-shinned Hawk","sci":"Accipiter striatus","caption":"Adult (left), immature (right)","season":"Year-round","id":"A small, long-tailed hawk with a rounded head. Blue-gray above with rusty barring below and a square-tipped tail crossed by thick dark bands; juveniles are brown.","habitat":"Forests and forest edges, including wooded city parks, suburbs, and cemeteries. Sometimes hunts birds at feeders.","behavior":"Stealthy and quick. Bursts from a hidden perch to chase songbirds in a short, agile pursuit through cover.","diet":["Birds and Eggs","Mammals"],"group":"raptors"},{"code":"COHA","name":"Cooper's Hawk","sci":"Astur cooperii","caption":"","season":"Year-round","id":"A medium, long-tailed hawk with a flat-topped, blocky head. Blue-gray above with rusty barring below and a rounded tail crossed by thick dark bands. The pale nape contrasts with the darker cap; juveniles are brown.","habitat":"Forests, woodlands, city parks, suburbs, and cemeteries. Often hunts birds at feeders.","behavior":"Launches from a perch in a burst of speed to chase prey, less acrobatic than the Sharp-shinned Hawk but more powerful. Favorite prey is doves and pigeons.","diet":["Birds and Eggs","Mammals"],"group":"raptors"},{"code":"BAEA","name":"Bald Eagle","sci":"Haliaeetus leucocephalus","caption":"","season":"Year-round, more common in winter","id":"A very large raptor with a heavy hooked yellow bill. Adults have a white head and tail and a dark brown body; immatures are mottled brown and white and take 4–5 years to reach adult plumage.","habitat":"Around lakes, reservoirs, and rivers with mature trees, where they build huge stick nests high in the canopy.","behavior":"Often seen soaring overhead or perched in tall trees near water. Solitary or in pairs in spring and summer, but gathers at feeding sites in winter. Will harass Ospreys to steal their catch.","diet":["Aquatic Vertebrates","Birds and Eggs","Mammals","Amphibians and Reptiles","Carrion"],"group":"raptors"},{"code":"SWHA","name":"Swainson's Hawk","sci":"Buteo swainsoni","caption":"© Ryan Parker","season":"Spring–Summer","id":"A large hawk with long, pointed wingtips. Adults are brown above and white below, with a white throat and dark brown \"bib\" across the chest.","habitat":"Open country with scattered trees, including open-space parks and farmland at the edges of town. Often perches on fenceposts and utility poles.","behavior":"Hunts insects and small mammals from the air and on the ground. Often snatches grasshoppers in midair and eats them on the wing.","diet":["Terrestrial or Flying Invertebrates","Mammals"],"group":"raptors"},{"code":"RTHA","name":"Red-tailed Hawk","sci":"Buteo jamaicensis","caption":"","season":"Year-round","id":"A common, large hawk with several color forms. Most are chocolate brown above and pale below, with a streaky belly band and a rusty red tail. In flight, look for dark bars along the leading edge of the underwing.","habitat":"Any open habitat. Look for them on utility poles, lone trees, and field edges. Nests high in tall trees and occasionally on billboards or building ledges.","behavior":"Often soars in wide circles overhead, then drops in a slow, deliberate dive with legs outstretched. The piercing \"keeer\" call is the screech you hear in nearly every Hollywood eagle scene.","diet":["Mammals","Amphibians and Reptiles","Birds and Eggs"],"group":"raptors"},{"code":"EASO","name":"Eastern Screech-Owl","sci":"Megascops asio","caption":"© Brandt Ryder","season":"Year-round","id":"A small owl with dark streaks and fine barring, short ear tufts, and yellow eyes. The common gray morph is overall gray; the rare red morph is rich rufous.","habitat":"Wooded suburbs, farmland, and city parks.","behavior":"A nocturnal hunter, also active at dawn and dusk. Swoops from a perch to catch insects, bats, small mammals, and amphibians. Nests in tree cavities and readily uses nest boxes.","diet":["Aquatic Invertebrates","Amphibians and Reptiles","Terrestrial or Flying Invertebrates","Birds and Eggs","Mammals"],"group":"raptors"},{"code":"GHOW","name":"Great Horned Owl","sci":"Bubo virginianus","caption":"","season":"Year-round","id":"A large, mottled brown-and-gray owl with a white throat patch, rusty face, and two prominent ear tufts.","habitat":"Woods mixed with open areas, including city parks and suburban yards. Often takes over old hawk or crow nests, and will use large nest boxes.","behavior":"Mostly nocturnal but often seen at dawn and dusk. Listen for the deep, rhythmic \"hoo-h'HOO-hoo-hoo.\" As a top predator, it's frequently mobbed by crows, ravens, and smaller raptors.","diet":["Mammals","Birds and Eggs","Amphibians and Reptiles"],"group":"raptors"},{"code":"BEKI","name":"Belted Kingfisher","sci":"Megaceryle alcyon","caption":"Male (left), female (right)","season":"Year-round","id":"A stocky bird with a big head, shaggy crest, and thick straight bill. Blue-gray above and white below with a blue-gray chest band; females also wear a rusty belly band.","habitat":"Common around city ponds, reservoirs, and rivers, especially where soft banks allow nest burrows.","behavior":"Perches in trees over water and hunts by diving from a hover or perch. The loud, dry rattle call carries across the water.","diet":["Aquatic Vertebrates","Aquatic Invertebrates"],"group":"waterbirds"},{"code":"DOWO","name":"Downy Woodpecker","sci":"Dryobates pubescens","caption":"","season":"Year-round","id":"A small black-and-white woodpecker with a short, stubby bill and black spots on the white outer tail feathers. Males have a small red patch on the back of the head.","habitat":"Wooded urban and suburban neighborhoods. A regular at feeders for suet, black-oil sunflower, millet, and peanuts; nests in tree cavities.","behavior":"Moves nimbly along trunks, small branches, and even tall weed stems to find insects. Flies in a bouncing flap-flap-glide pattern.","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds","Vegetation"],"group":"woodpeckers"},{"code":"HAWO","name":"Hairy Woodpecker","sci":"Dryobates villosus","caption":"","season":"Year-round","id":"Looks like a larger Downy Woodpecker, but with a bill nearly as long as the head and clean white outer tail feathers. Males have a red patch on the back of the head.","habitat":"Wooded neighborhoods and parks. A regular at feeders for suet, black-oil sunflower, and peanuts; nests in dead trees.","behavior":"Works tree trunks and main branches, moving easily up, down, and sideways. Drums on wood in fast, even bursts.","diet":["Terrestrial or Flying Invertebrates","Seeds","Fruits"],"group":"woodpeckers"},{"code":"NOFL","name":"Northern Flicker","sci":"Colaptes auratus","caption":"","season":"Year-round","id":"A large, brown woodpecker with a slightly curved bill, a black chest bib, spotted belly, and barred back. A flash of white rump shows in flight; wing and tail undersides are yellow (eastern) or red (western).","habitat":"Open woodlands, city parks, and suburbs. Uses nest boxes, drinks from bird baths, and occasionally visits large hopper or platform feeders, especially for suet.","behavior":"Feeds on ants and beetles on the ground, flushing to a tree if disturbed. Often perches upright on a branch rather than clinging to a trunk. Flight is a strong flap-and-glide.","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds"],"group":"woodpeckers"},{"code":"AMKE","name":"American Kestrel","sci":"Falco sparverius","caption":"Male (left), female (right)","season":"Year-round","id":"A small, slim falcon with long pointed wings and a long, square-tipped tail. Rusty back, two vertical black face stripes, and a blue head with a rusty cap; males also have blue-gray wings.","habitat":"Open areas and grasslands. In town, look for them perched on fenceposts, utility poles, and wires near city parks. Uses nest boxes.","behavior":"Often pumps its tail while perched. Hunts by dropping onto prey on the ground, sometimes hovering in place first while scanning.","diet":["Terrestrial or Flying Invertebrates","Mammals","Amphibians and Reptiles","Birds and Eggs"],"group":"raptors"},{"code":"WEKI","name":"Western Kingbird","sci":"Tyrannus verticalis","caption":"© Tony Leukering","season":"Spring–Summer","id":"A large flycatcher with a gray head, white throat, and bright yellow belly. White outer tail feathers flash in flight.","habitat":"Farm fields, roadsides, and open suburbs. Perches on trees, fences, and utility lines.","behavior":"Sallies out from an exposed perch to snap up flying insects. Loud and aggressive in defending its territory and nest.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"WEWP","name":"Western Wood-Pewee","sci":"Contopus sordidulus","caption":"© \"Western wood pewee\" by Petrified ForestNPS, Public Domain Mark","season":"Spring–Summer","id":"A small, brownish-gray flycatcher with two pale wing bars and a gray \"vest\" across the chest, paler in the center.","habitat":"Open woodlands and forest edges, especially aspen and cottonwood groves. Common in city parks along wooded streams.","behavior":"Perches on bare tree limbs and sallies out to catch insects, often returning to the same perch. Listen for the nasal, drawn-out \"pee-wee\" call.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"SAPH","name":"Say's Phoebe","sci":"Sayornis saya","caption":"","season":"Spring–Summer","id":"A small flycatcher, brownish gray above with a warm rusty belly and dark tail. The rounded head can look peaked when feathers are raised.","habitat":"Grasslands, shrublands, and open-space parks. Often nests under building eaves, and will use a well-placed nest shelf.","behavior":"Perches on low shrubs and fences, sallying out to catch insects and returning to the same spot. Occasionally wags its tail.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"NSHR","name":"Northern Shrike","sci":"Lanius borealis","caption":"© Colin Woolley","season":"Winter","id":"A robin-sized songbird with a stout, hooked bill. Pale gray above and white below, with black wings, tail, and face mask.","habitat":"Open areas with scattered thickets. Often perches quietly in brushy patches; sometimes hunts smaller birds near feeders.","behavior":"Catches insects in the air with its bill and seizes larger prey with its feet, often impaling the catch on thorns or barbed wire to store it. Defends a winter territory, so a bird seen one day is often back the next.","diet":["Terrestrial or Flying Invertebrates","Birds and Eggs","Amphibians and Reptiles"],"group":"songbirds"},{"code":"BLJA","name":"Blue Jay","sci":"Cyanocitta cristata","caption":"","season":"Year-round","id":"A large, crested songbird, bright blue above and white below. Wings and tail are barred with black and white, and a thin black collar rings the head.","habitat":"Forest edges, open woodlands, parks, and suburban neighborhoods. A frequent feeder visitor; prefers tray or hopper feeders with seeds, peanuts, and suet.","behavior":"Clever, noisy, and bold, often imitating the screams of Red-tailed Hawks. Raises and lowers its crest to communicate mood with other jays.","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds"],"group":"songbirds"},{"code":"BBMA","name":"Black-billed Magpie","sci":"Pica hudsonia","caption":"","season":"Year-round","id":"A large, long-tailed songbird, boldly black and white with iridescent blue-green flashes on the wings and tail.","habitat":"Open woodlands, city parks, and urban neighborhoods. Builds very large stick nests, often along stream corridors; occasionally visits platform and suet feeders.","behavior":"Curious and social, foraging in loose flocks and walking with a long-strided swagger. Bands together to mob birds of prey, surrounding and scolding them.","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds","Mammals","Carrion"],"group":"songbirds"},{"code":"AMCR","name":"American Crow","sci":"Corvus brachyrhynchos","caption":"","season":"Year-round","id":"An all-black bird with a thick bill and short, square tail. Smaller than a raven, with steadier wingbeats.","habitat":"Thrives around people. Common in parks, golf courses, lawns, parking lots, athletic fields, roadsides, and landfills. Visits platform feeders.","behavior":"Social and curious, with the familiar \"caw\" call. Gathers in large groups and frequently mobs larger birds. Flies with steady, rowing wingbeats rather than long glides.","diet":["Terrestrial or Flying Invertebrates","Aquatic Vertebrates","Aquatic Invertebrates","Seeds","Fruits","Carrion"],"group":"songbirds"},{"code":"CORA","name":"Common Raven","sci":"Corvus corax","caption":"","season":"Year-round","id":"A large black bird with a shaggy throat, heavy bill, and wedge-shaped tail. Bigger than a crow, with longer wings.","habitat":"Nearly any habitat. Look for them in open-space parks, landfills, near airports, and along country roadsides; visits platform feeders.","behavior":"Curious, clever, and almost omnivorous. Usually seen alone or in pairs. Flight is easy and graceful, with slow wingbeats and frequent soaring. Listen for a low, gurgling croak.","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds","Carrion","Mammals","Birds and Eggs","Amphibians and Reptiles","Aquatic Vertebrates"],"group":"songbirds"},{"code":"BCCH","name":"Black-capped Chickadee","sci":"Poecile atricapillus","caption":"","season":"Year-round","id":"A tiny, big-headed bird with a black cap and bib, white cheeks, gray back, and buffy sides.","habitat":"Forests, shrublands, city parks, and tree-filled suburbs. Easy to attract to feeders and nest boxes.","behavior":"Curious, social, and active. Often joins mixed flocks of other songbirds. Listen for the \"chickadee-dee-dee\" call and the clear whistled song that sounds like \"cheese-bur-ger.\"","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds"],"group":"songbirds"},{"code":"VGSW","name":"Violet-green Swallow","sci":"Tachycineta thalassina","caption":"","season":"Spring–Summer","id":"A small swallow with a tiny bill. Bright iridescent green back, purplish wings, and clean white underparts; white side patches almost wrap over the rump.","habitat":"Open woodlands near water, including city parks, lakes, ponds, and streams. Uses nest boxes placed near water.","behavior":"Forages in large groups, catching insects on the wing. Flight is quick, with shallow wingbeats and long glides.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"BARS","name":"Barn Swallow","sci":"Hirundo rustica","caption":"","season":"Spring–Summer","id":"A sleek swallow with a deeply forked tail. Dark blue above with a reddish forehead and throat and warm orange underparts.","habitat":"Grasslands and open woodlands near water. Builds mud nests on eaves, rafters, and inside open sheds. Crushed eggshells on a platform feeder may attract them.","behavior":"Forages in large groups with swifts and other swallows, catching insects in flight. Often hunts low, just inches above the water or ground.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"CLSW","name":"Cliff Swallow","sci":"Petrochelidon pyrrhonota","caption":"","season":"Spring–Summer","id":"A compact, square-tailed swallow with a dark blue cap, white forehead \"headlamp,\" rusty rump, and pale belly.","habitat":"Grasslands, golf courses, and city parks near water. Builds gourd-shaped mud nests in colonies under bridges, overpasses, and culverts.","behavior":"Forages, nests, preens, and bathes in large groups. In mixed swallow flocks, often hunts insects higher in the air.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"BUSH","name":"Bushtit","sci":"Psaltriparus minimus","caption":"","season":"Year-round","id":"A tiny, round songbird with a big head, short bill, and long tail. Plain brownish gray overall, slightly darker above.","habitat":"Shrublands, city parks, and suburban yards. Hard to attract to feeders, but native shrubs bring in the insects they prefer.","behavior":"Travels in busy flocks, often mixed with chickadees, gleaning insects and spiders from leaves and sometimes hanging upside down. Stays in touch with wispy, high-pitched contact notes.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"CEDW","name":"Cedar Waxwing","sci":"Bombycilla cedrorum","caption":"","season":"Year-round","id":"A sleek, crested songbird with a black face mask, soft brown chest, pale yellow belly, and a tail tipped in bright yellow. Bright red wax-like dots on the wingtips give the bird its name.","habitat":"Woodlands, parks, and gardens with fruiting shrubs and trees. Native berries and fruit on a platform feeder may bring them in.","behavior":"Highly social, traveling in tight flocks. Plucks berries one at a time and swallows them whole.","diet":["Fruits","Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"RBNU","name":"Red-breasted Nuthatch","sci":"Sitta canadensis","caption":"© Colin Woolley","season":"Year-round","id":"A small, compact songbird with a sharp bill, short tail, and gray back. Males have a black cap, white eyebrow, black eye stripe, and rusty underparts; females are paler with a gray cap. Listen for a nasal \"yank-yank,\" like a tiny tin horn.","habitat":"Mainly conifer forests; visits parks and yards in winter, and comes to feeders.","behavior":"Climbs trunks and branches in every direction, often headfirst down a tree. Pushy at feeders, and flies short distances in a bouncing pattern. Excavates its own nest cavity.","diet":["Terrestrial or Flying Invertebrates","Seeds"],"group":"songbirds"},{"code":"WBNU","name":"White-breasted Nuthatch","sci":"Sitta carolinensis","caption":"","season":"Year-round","id":"A small, compact songbird with a gray back, white face and underparts, and rusty patches near the legs. Males have a black cap; females show a gray cap with a black nape.","habitat":"Mature deciduous forests, plus parks and yards with large trees. A regular at feeders.","behavior":"Quick and active, climbing trunks and branches in any direction. Listen for a fast, nasal \"ha-ha-ha\" lasting two or three seconds.","diet":["Terrestrial or Flying Invertebrates","Seeds","Fruits"],"group":"songbirds"},{"code":"HOWR","name":"Northern House Wren","sci":"Troglodytes aedon","caption":"","season":"Spring–Summer","id":"A tiny, compact wren with a thin, slightly curved bill and a tail often cocked straight up. Plain brown overall with darker barring on the wings and tail.","habitat":"Open woodlands and yards with scattered trees and shrubs. Readily uses nest boxes; brush piles offer cover and insect food.","behavior":"Active and vocal, working through dense cover and pausing to deliver a long, bubbly, warbling song.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"GRCA","name":"Gray Catbird","sci":"Dumetella carolinensis","caption":"","season":"Spring–Summer","id":"A slim, medium-sized bird with a long tail and long legs. Slate gray overall with a black cap, dark tail, and a rusty patch beneath the tail. Listen for a flat, cat-like \"mew.\"","habitat":"Thick shrubs and vine tangles. Fruiting trees and shrubs help bring them into yards.","behavior":"Related to mockingbirds and a skilled mimic, mixing imitations into a long, jumbled song. Sticks close to cover, usually flying low and short between thickets, then flitting branch to branch.","diet":["Terrestrial or Flying Invertebrates","Fruits"],"group":"songbirds"},{"code":"EUST","name":"European Starling","sci":"Sturnus vulgaris","caption":"","season":"Year-round","id":"A stocky songbird with a short tail and long, slender bill. In winter, it's iridescent black with creamy spots and a dark bill; by summer, the spots wear off and the bill turns bright yellow.","habitat":"Woodlands, grasslands, lawns, and parking lots. Perches on buildings and wires, nests in almost any cavity in trees or buildings, and is a regular feeder visitor.","behavior":"Travels and forages in large, often mixed flocks. The song is a noisy mix of warbles, whistles, and convincing imitations of other birds.","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds"],"group":"songbirds"},{"code":"AMRO","name":"American Robin","sci":"Turdus migratorius","caption":"","season":"Year-round","id":"A medium songbird with a dark gray head, yellow bill, and warm orange breast. The classic \"robin red-breast.\"","habitat":"Gardens, lawns, fields, city parks, and shrubby woodlands. Occasionally visits feeders for mealworms, fruit, or suet.","behavior":"Forages on the ground in classic run-and-pause style, hunting for earthworms. Sings a rich, caroling song. In fall and winter, large flocks move into fruiting trees.","diet":["Terrestrial or Flying Invertebrates","Fruits"],"group":"songbirds"},{"code":"HOSP","name":"House Sparrow","sci":"Passer domesticus","caption":"Male (left) and female (right). © \"House Sparrow\" by Mathias Appel, Public Domain Dedication (CC0).","season":"Year-round","id":"A chunky sparrow with a stout bill and short tail. Males have a gray crown, white cheeks, chestnut nape, and black throat; females are plain brown with a streaky back.","habitat":"Urban and suburban areas. A frequent feeder visitor for millet, corn, and sunflower seeds. Uses nest boxes.","behavior":"Social and noisy, foraging in flocks and hopping along the ground.","diet":["Seeds","Terrestrial or Flying Invertebrates","Fruits"],"group":"songbirds"},{"code":"HOFI","name":"House Finch","sci":"Haemorhous mexicanus","caption":"Male (left), female (right)","season":"Year-round","id":"A small finch with a thick, conical bill. Grayish brown with heavy streaking on the breast; males also show a red head and chest.","habitat":"Grasslands, open coniferous forests, and urban and suburban yards. Uses most feeder types, may nest in a backyard, and often perches on trees and power lines.","behavior":"Very social, usually in flocks. Flight is bouncy. Sits still on a feeder while shelling seeds with its strong bill.","diet":["Seeds","Fruits"],"group":"songbirds"},{"code":"AMGO","name":"American Goldfinch","sci":"Spinus tristis","caption":"Male (left): © Courtney Celley; Female (right): © \"American Goldfinch\" by Shenandoah National Park, Public Domain Mark","season":"Year-round","id":"A small finch with bold white wingbars. Breeding males are brilliant yellow with black wings, tail, and forehead; females are duller yellow-green. Non-breeding birds are dull yellow-brown to gray.","habitat":"Patches of sunflower, aster, and thistle, plus suburban yards, parks, and gardens.","behavior":"Balances on flower heads to pick out seeds. Forages in flocks outside the breeding season.","diet":["Seeds"],"group":"songbirds"},{"code":"CHSP","name":"Chipping Sparrow","sci":"Spizella passerina","caption":"","season":"Spring–Fall","id":"A slim, long-tailed sparrow with streaky brown upperparts and a clean gray underside. Adults have a bright rusty cap, black eye line, and dark bill; immatures are paler.","habitat":"Open woodlands, city parks, golf courses, cemeteries, and gardens with evergreens. Visits hopper, platform, and ground feeders, and may nest in backyard shrubs or trees.","behavior":"Hops along the ground close to cover for a quick retreat. Males sing a long, dry trill from the outer branches of trees.","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds"],"group":"songbirds"},{"code":"DEJU","name":"Dark-eyed Junco","sci":"Junco hyemalis","caption":"","season":"Winter","id":"A small sparrow with a pink bill and crisp white outer tail feathers that flash in flight. Several forms occur along the Front Range — Oregon, Slate-colored, Pink-sided, and White-winged — ranging from gray to brown.","habitat":"Woodlands, fields, suburban parks, roadsides, and gardens.","behavior":"Flashes white tail feathers in flight. Hops on the ground or works through low underbrush in flocks, often mixing several junco forms together with other sparrows and bluebirds in winter.","diet":["Seeds","Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"WCSP","name":"White-crowned Sparrow","sci":"Zonotrichia leucophrys","caption":"","season":"Fall–Spring","id":"A medium sparrow with bold black-and-white crown stripes, a gray face and chest, and streaky brown wings with two white wingbars.","habitat":"Brushy edges of grasslands, roadsides, city parks, and gardens. Visits feeders but prefers seed on the ground; brush piles encourage them to stay.","behavior":"Feeds on the ground or low in shrubs, hopping and scratching through leaf litter for seeds.","diet":["Terrestrial or Flying Invertebrates","Seeds","Fruits"],"group":"songbirds"},{"code":"SOSP","name":"Song Sparrow","sci":"Melospiza melodia","caption":"","season":"Year-round","id":"A medium sparrow with gray-and-brown head stripes and heavy streaking on the chest that converges into a dark central spot.","habitat":"Brushy areas near streams, wetlands, and grasslands, plus city parks and gardens. Regularly visits platform and ground feeders.","behavior":"Flies short distances and forages on the ground by walking and hopping. Males sing a clear, varied song from open perches.","diet":["Terrestrial or Flying Invertebrates","Seeds","Fruits"],"group":"songbirds"},{"code":"SPTO","name":"Spotted Towhee","sci":"Pipilo maculatus","caption":"Male (left), female (right): © Will Elder / NPS","season":"Year-round","id":"A large, bold sparrow with a black head, back, wings, and tail; white spots on the wings; rusty sides; white belly; and piercing red eyes.","habitat":"Dense shrub thickets and woodland understory with deep leaf litter.","behavior":"Forages in leaf litter with a distinctive two-footed backward scratch. Sings from the tops of bushes in spring.","diet":["Terrestrial or Flying Invertebrates","Seeds","Fruits"],"group":"songbirds"},{"code":"WEME","name":"Western Meadowlark","sci":"Sturnella neglecta","caption":"© Colin Woolley","season":"Year-round","id":"A chunky, medium-sized songbird with a long, slender bill. Streaky brown above, bright yellow below, with a black \"V\" across the chest; white outer tail feathers flash in flight.","habitat":"Grasslands and other open country with low vegetation — vacant lots, roadsides, and farm fields.","behavior":"Forages and nests on the ground. Males sing a clear, flutelike song that carries across open country.","diet":["Terrestrial or Flying Invertebrates","Seeds"],"group":"songbirds"},{"code":"BUOR","name":"Bullock's Oriole","sci":"Icterus bullockii","caption":"Male (left): © Sarah Driscoll; Female (right): \"Bullock's Oriole at Seedskadee National Wildlife Refuge\" by USFWS Mountain-Prairie, Public Domain Mark","season":"Spring–Summer","id":"A sturdy songbird with a long, pointed bill. Males are flame orange with a black crown, eye stripe, throat, and back, and bold white wing patches. Females are yellow on the head, chest, and tail with a grayish back.","habitat":"Open woodlands near streams, city parks, and suburban gardens. Comes to feeders for cut oranges and sugar water.","behavior":"Hops energetically through branches searching for insects, fruit, and nectar, sometimes hanging upside down. Weaves a long, gourd-shaped hanging pouch nest.","diet":["Terrestrial or Flying Invertebrates","Fruits","Nectar"],"group":"songbirds"},{"code":"RWBL","name":"Red-winged Blackbird","sci":"Agelaius phoeniceus","caption":"Male (left), female (right): © Colin Woolley","season":"Year-round","id":"Males are glossy black with bright red shoulder patches edged in yellow. Females are sparrow-like, heavily streaked brown with a pale eyebrow. Both have slender, pointed bills.","habitat":"Wetlands and damp edges of city parks, golf courses, and roadsides. Feeds from the ground or from tube, hopper, and platform feeders.","behavior":"In spring, males sing \"conk-la-ree!\" from cattails and fenceposts to defend their territories. In winter, gathers in huge flocks with other blackbirds and starlings to feed in grain fields.","diet":["Terrestrial or Flying Invertebrates","Seeds"],"group":"songbirds"},{"code":"BHCO","name":"Brown-headed Cowbird","sci":"Molothrus ater","caption":"Male (left), female (right)","season":"Spring–Summer","id":"A stocky blackbird with a thick, conical bill and short tail. Males are glossy black with a chocolate brown head; females are plain grayish brown.","habitat":"Open areas, including fields, city park lawns, and suburbs. Visits large hopper and platform feeders or feeds on the ground.","behavior":"A nest parasite — females lay their eggs in other songbirds' nests for those birds to raise. Forages on the ground with blackbirds and starlings, and sometimes perches on livestock to grab insects the animals flush.","diet":["Terrestrial or Flying Invertebrates","Seeds"],"group":"songbirds"},{"code":"COGR","name":"Common Grackle","sci":"Quiscalus quiscula","caption":"","season":"Spring–Summer","id":"A lanky blackbird with a long, keeled tail, heavy curved bill, and bright yellow eyes. Males are iridescent, with a blue head and bronzy body; females are duller.","habitat":"Open woodlands, fields, city parks, suburban lawns, and farm fields. Visits hopper, platform, and ground feeders.","behavior":"Chatty, with a creaky song that sounds like a rusty gate. Flocks with other blackbirds and starlings in winter, and dominates other birds at feeders.","diet":["Seeds","Terrestrial or Flying Invertebrates","Mammals","Birds and Eggs","Amphibians and Reptiles"],"group":"songbirds"},{"code":"YEWA","name":"Northern Yellow Warbler","sci":"Setophaga petechia","caption":"","season":"Spring–Summer","id":"A small, almost entirely yellow songbird. Males show fine reddish streaks on the chest; females and immatures are paler with a hint of gray on the face and back. Listen for a sweet, accelerating song: \"sweet sweet sweet I'm-so-sweet.\"","habitat":"Willow thickets and shrubby woods, usually near water.","behavior":"Flits through leaves picking off small insects. Males sing from the tops of trees and shrubs to defend their territory.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"YWRA","name":"Yellow-rumped Warbler","sci":"Setophaga coronata","caption":"Male (left), female (right): © Colin Woolley","season":"Spring–Fall","id":"A small, active warbler, gray with black streaking and bright yellow patches on the rump and sides. White wing bars and a broken white eye ring.","habitat":"Coniferous and deciduous woodlands. In fall and winter, drops down into neighborhoods and parks.","behavior":"Moves quickly through bark, needles, and leaves looking for insects, and often darts out to catch them in midair.","diet":["Terrestrial or Flying Invertebrates","Fruits","Seeds"],"group":"songbirds"},{"code":"WIWA","name":"Wilson's Warbler","sci":"Cardellina pusilla","caption":"","season":"Spring and Fall","id":"A small, lively warbler, bright yellow overall with an olive back. Males wear a bold black cap; females are similar but with little or no black above.","habitat":"Shrubby habitats near water, forest edges, and clearings.","behavior":"Forages low in understory and shrubs, gleaning insects from leaves and branches. Occasionally darts out to catch flying insects.","diet":["Terrestrial or Flying Invertebrates"],"group":"songbirds"},{"code":"WETE","name":"Western Tanager","sci":"Piranga ludoviciana","caption":"© Sarah Driscoll","season":"Spring–Summer","id":"Males are bright yellow with black wings, a black back, and a flame-red head; females are duller yellow with gray-brown wings and lack the red head.","habitat":"Breeds in coniferous forests. During migration, can turn up almost anywhere, including yards, parks, and gardens.","behavior":"Forages high in the treetops and makes quick flights to snatch insects in midair.","diet":["Terrestrial or Flying Invertebrates","Fruits"],"group":"songbirds"}];
